const input = $json.body || $json || {};
const evento = input.evento || 'recuperar_password';
const datos = input.datos || {};
// El nombre lo escribe quien se registra, y el email puede llegar a un tercero: se escapa todo.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const nombre = esc(datos.nombre || 'Productor');
const email = datos.email || '';

let asunto, html;
if (evento === 'verificar_email') {
  const url = esc(datos.verificarUrl || '#');
  asunto = '✅ Confirmá tu email - AgroTech';
  html = '<h2>✅ Confirmá tu email</h2>' +
    '<p>Hola ' + nombre + ',</p>' +
    '<p>Gracias por registrarte en AgroTech. Para activar los avisos por email y WhatsApp, confirmá que este email es tuyo (el link vale 24 horas):</p>' +
    '<p><a href="' + url + '" style="background:#059669;color:white;padding:12px 20px;border-radius:8px;text-decoration:none;font-weight:bold;display:inline-block;">Confirmar mi email</a></p>' +
    '<p>Si el botón no funciona, copiá y pegá este link en el navegador:</p>' +
    '<p>' + url + '</p>' +
    '<p>Si no creaste una cuenta en AgroTech, podés ignorar este correo.</p>';
} else {
  const resetUrl = esc(datos.resetUrl || '#');
  asunto = '🔑 Recuperar contraseña - AgroTech';
  html = '<h2>🔑 Recuperar contraseña</h2>' +
    '<p>Hola ' + nombre + ',</p>' +
    '<p>Recibimos un pedido para restablecer tu contraseña de AgroTech. Si fuiste vos, hacé clic en el siguiente link (válido por 1 hora):</p>' +
    '<p><a href="' + resetUrl + '" style="background:#059669;color:white;padding:12px 20px;border-radius:8px;text-decoration:none;font-weight:bold;display:inline-block;">Restablecer contraseña</a></p>' +
    '<p>Si el botón no funciona, copiá y pegá este link en el navegador:</p>' +
    '<p>' + resetUrl + '</p>' +
    '<p>Si no pediste este cambio, podés ignorar este correo — tu contraseña sigue siendo la misma.</p>';
}

return [{ json: { email, asunto, html } }];
